import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n, m = map(int, input[index:index+2])
        index += 2
        a = list(map(int, input[index:index+n]))
        index += n
        k = int(input[index])
        index += 1
        b = list(map(int, input[index:index+k]))
        index += k
        stack = deque()
        for num in reversed(a):
            stack.append(num)
        result = "Yes"
        for num in reversed(b):
            while stack and num != stack[-1]:
                if stack[-1] % m == 0:
                    top = stack.pop()
                    for _ in range(m):
                        stack.append(top // m)
                else:
                    result = "No"
                    break
            if stack and num == stack[-1]:
                stack.pop()
            else:
                result = "No"
                break
        if stack:
            result = "No"
        results.append(result)
    for res in results:
        print(res)

if __name__ == "__main__":
    main()
